-- Living areas for all of Japan instead of the seven "ward – station" sample areas of north Tokyo.
-- An area is now a municipality (市区町村) by its official code (全国地方公共団体コード, 6 digits with the check digit);
-- the 20 designated cities (政令指定都市) are split into their wards (区), Tokyo's 23 special wards are municipalities.
-- No station any more. Users keep pointing at areas.id (users.area_id, places.area_id), so the code that joins areas
-- does not change; prefectures get their own table for the two-step picker.
--
-- Data: "Geolonia 住所データ" (https://github.com/geolonia/japanese-addresses-v2, api/ja.json, CC BY 4.0), made by
-- Geolonia from アドレス・ベース・レジストリ (デジタル庁). Names in kanji, kana and romaji, and a representative point
-- (lat/lng) per prefecture and area, used to open the map there and to suggest an area from a point on the map.
-- 1,892 areas: every municipality except the six villages of the Northern Territories.
--
-- areas.ward keeps the romaji name, station becomes optional, display_name = "Arakawa-ku, Tokyo · 東京都荒川区".
-- The seven old areas move to their ward (Arakawa – Nippori and Arakawa – Machiya both to Arakawa-ku) and are deleted.
-- Places in Japan without an area get the area whose point is nearest (rough near borders; only used for ordering).

CREATE TABLE prefectures (
  code       CHAR(2)      PRIMARY KEY,
  name_ja    VARCHAR(10)  NOT NULL,
  name_kana  VARCHAR(20)  NOT NULL,
  name_en    VARCHAR(20)  NOT NULL,
  lat        DECIMAL(9,6) NOT NULL,
  lng        DECIMAL(9,6) NOT NULL
) ENGINE=InnoDB;

ALTER TABLE areas
  MODIFY station VARCHAR(80) NULL,
  ADD COLUMN code            CHAR(6)      NULL AFTER id,
  ADD COLUMN prefecture_code CHAR(2)      NULL AFTER code,
  ADD COLUMN name_ja         VARCHAR(40)  NULL,
  ADD COLUMN name_kana       VARCHAR(80)  NULL,
  ADD COLUMN name_en         VARCHAR(80)  NULL,
  ADD COLUMN lat             DECIMAL(9,6) NULL,
  ADD COLUMN lng             DECIMAL(9,6) NULL,
  ADD CONSTRAINT uq_areas_code UNIQUE (code),
  ADD INDEX idx_areas_prefecture (prefecture_code, sort_order);










ALTER TABLE areas
  ADD CONSTRAINT fk_areas_prefecture FOREIGN KEY (prefecture_code) REFERENCES prefectures(code);

-- The seven sample areas → their Tokyo ward
UPDATE users u
  JOIN areas o ON o.id = u.area_id AND o.code IS NULL
  JOIN areas n ON n.prefecture_code = '13' AND n.ward = CONCAT(o.ward, '-ku')
SET u.area_id = n.id;

UPDATE places p
  JOIN areas o ON o.id = p.area_id AND o.code IS NULL
  JOIN areas n ON n.prefecture_code = '13' AND n.ward = CONCAT(o.ward, '-ku')
SET p.area_id = n.id;

UPDATE users SET area_id = NULL WHERE area_id IN (SELECT id FROM (SELECT id FROM areas WHERE code IS NULL) old);
UPDATE places SET area_id = NULL WHERE area_id IN (SELECT id FROM (SELECT id FROM areas WHERE code IS NULL) old);
DELETE FROM areas WHERE code IS NULL;

-- Places in Japan (by position) that have no area yet: the nearest area point
UPDATE places p
SET p.area_id = (SELECT a.id FROM areas a
                 ORDER BY POW(a.lat - p.lat, 2) + POW((a.lng - p.lng) * COS(RADIANS(p.lat)), 2), a.id
                 LIMIT 1)
WHERE p.area_id IS NULL AND p.lat BETWEEN 20 AND 46 AND p.lng BETWEEN 122 AND 154;
